import {features} from './conditions.js?v=range-20260914-1';
import {cardName} from './spoilers.js';
import {point,polygon} from './geometry.js';
import {theoreticalStats} from './card-stats.js';
const colors=['#101721','#ef7779','#e9ca72','#75c69c','#74ace3','#b497e0','#293b4c'],key=c=>c.slice(0,2).join(','),num=n=>n.toLocaleString('zh-CN'),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function preview(recipe){
 const cells=recipe.cells,points=cells.map(point),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),view=[Math.min(...xs)-24,Math.min(...ys)-24,Math.max(...xs)-Math.min(...xs)+48,Math.max(...ys)-Math.min(...ys)+48];
 const background=cells.map(c=>`<polygon points="${polygon(c)}" fill="${colors[c[2]]}" fill-opacity=".7" stroke="#465369" stroke-width="1"/>`).join('');
 return `<svg class="rank-preview" viewBox="${view.join(' ')}" role="img" aria-label="${escape(cardName(recipe))}的配方地图">${background}</svg>`;
}

try{
 const [ranking,data]=await Promise.all([fetch('ranking-data.json?v=ranking-audit-20260914-4').then(r=>r.json()),fetch('data.json').then(r=>r.json())]);
 const allRows=ranking.rows;let rows=ranking.rows.slice().sort((a,b)=>b.result.value-a.result.value||a.id-b.id),size=6;let pages=Math.max(1,Math.ceil(rows.length/size));let page=Math.min(pages,Math.max(1,Math.floor(Number(new URLSearchParams(location.search).get('page'))||1)));
 const params=new URLSearchParams(location.search),slotControl=document.getElementById('min-slots'),colorControl=document.getElementById('card-color'),rangeControl=document.getElementById('min-range');rangeControl.value=String(Math.max(1,Math.min(5,Number(params.get('range'))||1)));slotControl.value=String(Math.max(0,Math.min(3,Number(params.get('slots'))||0)));colorControl.value=String(Math.max(0,Math.min(5,Number(params.get('color'))||0)));
 const query=()=>`page=${page}&slots=${slotControl.value}&color=${colorControl.value}&range=${rangeControl.value}`;
 function filter(reset=false){const k=slotControl.value+':'+colorControl.value+':'+rangeControl.value;rows=allRows.flatMap(row=>{const i=row.conditions?.[k],result=i>=0?row.variants[i]:k==='0:0:1'?row.result:null;return result?[{...row,result}]:[]}).sort((a,b)=>b.result.value-a.result.value||a.id-b.id);pages=Math.max(1,Math.ceil(rows.length/size));page=reset?1:Math.min(page,pages);document.getElementById('coverage').textContent=`满足条件 ${rows.length} / ${ranking.totalRecipes} 张 · 无法满足 ${allRows.filter(r=>r.conditions?.[k]===-1).length} · 未找到 ${allRows.filter(r=>r.conditions?.[k]===-2).length}`;history.replaceState(null,'','ranking.html?'+query());render();}
 slotControl.onchange=colorControl.onchange=rangeControl.onchange=()=>filter(true);

 function render(){document.getElementById('ranking-grid').innerHTML=rows.slice((page-1)*size,page*size).map(row=>{const r=data.recipes.find(r=>r.id===row.id),f=features(r,row.result),s=theoreticalStats(r,row.result),rank=rows.findIndex(x=>x.result.value===row.result.value)+1,reached=row.result.value===row.upper;return `<a class="rank-card" href="index.html?saved=${r.id}&page=${page}&slots=${slotControl.value}&color=${colorControl.value}&range=${rangeControl.value}"><div class="rank-top"><span class="rank-number" style="color:${colors[r.color]}">${String(rank).padStart(2,'0')}</span><div><h2>${escape(cardName(r))}</h2><small>${escape(r.internal)} · ${escape(data.characters[r.character].name)}</small></div></div>${preview(r)}<div class="rank-info"><div class="rank-total">${num(row.result.value)}<small>可行解总属性</small></div><div class="rank-split"><span>威力 ${num(s.power)}</span><span>耐力 ${num(s.fortitude)}</span></div><div class="rank-meta"><span>${f.slots} 槽 · 范围 ${f.range} · ${s.strikes} 惩罚 · 粒子 ${row.result.placements.length}/${row.result.score.limit}</span><span>查看完整方案 ↗</span></div><div class="rank-bound"><span>理论上限 ${num(row.upper)}</span><span class="${reached?'reached':''}">${reached?'已达上限':'当前最佳'}</span></div></div></a>`}).join('')||'<p>没有已知方案满足当前槽位和颜色条件。</p>';
 const nav=document.getElementById('pagination');nav.innerHTML=`<button data-page="${page-1}" ${page===1?'disabled':''}>上一页</button>`+Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')+`<button data-page="${page+1}" ${page===pages?'disabled':''}>下一页</button>`;nav.querySelectorAll('button').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);history.replaceState(null,'','ranking.html?'+query());render();window.scrollTo({top:0,behavior:'smooth'})});}
 window.addEventListener('card-name-visibility',render);filter();
}catch(e){document.getElementById('coverage').textContent='加载失败';document.getElementById('ranking-grid').textContent='无法加载排名：'+e.message;}
